def word_frequency(text: str) -> dict[str, int]:
    import string
    counts: dict[str, int] = {}
    for token in text.split():
        word = token.strip(string.punctuation).lower()
        if word:
            counts[word] = counts.get(word, 0) + 1
    return counts
